 void RemoveLeanPose(){if(!eye)return;eye.transform.localPosition-=appliedLean;eye.transform.localRotation*=Quaternion.Inverse(appliedLeanRoll);appliedLean=Vector3.zero;appliedLeanRoll=Quaternion.identity;}
 public void ResetLean(){RemoveLeanPose();lean=0;}
 public void AdvanceLean(float dt,float input){RemoveLeanPose();lean=Mathf.Lerp(lean,Mathf.Clamp(input,-1,1),1-Mathf.Exp(-dt*12));Vector3 local=new Vector3(lean*.28f,-Mathf.Abs(lean)*.035f,0);Vector3 world=eye.transform.parent.TransformVector(local);float length=world.magnitude;float allowed=length;Vector3 origin=eye.transform.position;if(length>.0001f){foreach(var hit in Physics.SphereCastAll(origin,.12f,world/length,length,~0,QueryTriggerInteraction.Ignore)){if(hit.collider.transform.IsChildOf(transform))continue;allowed=Mathf.Min(allowed,Mathf.Max(0,hit.distance-.025f));}foreach(var collider in Physics.OverlapSphere(origin,.115f,~0,QueryTriggerInteraction.Ignore))if(!collider.transform.IsChildOf(transform)){allowed=0;break;}}float fraction=length>.0001f?allowed/length:1;lean*=fraction;appliedLean=local*fraction;appliedLeanRoll=Quaternion.Euler(0,0,-lean*8);eye.transform.localPosition+=appliedLean;eye.transform.localRotation*=appliedLeanRoll;}
 public void TapTorch(float now){if(!torch)return;if(battery<=0){torch.enabled=false;if(equipment&&equipment.UseSupply("torch_cell")){resumeTorchAfterCell=true;torchNotice="Replacing torch battery…";}else torchNotice=equipment&&equipment.ActionBusy?"Battery replacement in progress":"Torch battery empty · Open backpack for a spare cell";torchNoticeUntil=Time.unscaledTime+4;return;}if(now-lastTorchTap<=.3f){whiteHeadlight=!whiteHeadlight;ApplyTorchMode();torch.enabled=battery>0;lastTorchTap=-10;}else{torch.enabled=!torch.enabled&&battery>0;lastTorchTap=now;}}
 public void TorchCellFitted(){if(resumeTorchAfterCell){ApplyTorchMode();torch.enabled=true;resumeTorchAfterCell=false;}torchNotice="Fresh torch battery fitted";torchNoticeUntil=Time.unscaledTime+3;}
 public void ApplyTorchMode(){if(!torch)return;torch.color=whiteHeadlight?new Color(1,.95f,.85f):new Color(1,.035f,.015f);torch.intensity=whiteHeadlight?WhiteTorchPower:RedTorchPower;torch.range=whiteHeadlight?32:23;torch.spotAngle=whiteHeadlight?52:58;torch.innerSpotAngle=whiteHeadlight?30:28;}
 public float ExertionSpeed(float dt,bool wantsSprint,bool moving){
 float weight=inventory?inventory.Weight:8;float load=Mathf.Clamp01(weight/24f);
 if(exhausted&&stamina>.28f)exhausted=false;
 IsSprinting=wantsSprint&&moving&&!exhausted&&stamina>0;
 if(IsSprinting){stamina=Mathf.Max(0,stamina-dt*Mathf.Lerp(.038f,.085f,load));recoveryDelay=1.6f;if(stamina<=0){exhausted=true;IsSprinting=false;}}
 else {recoveryDelay=Mathf.Max(0,recoveryDelay-dt);if(recoveryDelay<=0)stamina=Mathf.Min(1,stamina+dt*Mathf.Lerp(.13f,.065f,load)*(moving?.65f:1));}
 return IsSprinting?Mathf.Lerp(3.8f,3.2f,load)*Mathf.Lerp(.9f,1,stamina):2.1f;
 }
 public void ReturnToCheckpoint(){ResetLean();anatomy.ResetForCheckpoint();suppression=suppressionVisual=suppressionHold=0;stamina=1;exhausted=false;recoveryDelay=0;body.enabled=false;transform.position=checkpoint;eye.transform.localPosition=standingEye;pitch=0;headYaw=0;eye.transform.localRotation=Quaternion.identity;body.enabled=true;fallStart=checkpoint.y;lastFoot=checkpoint;if(inventory)inventory.Save();}
