 public void AdvanceCinematicPose(float dt,float movement,bool aim=false){t+=Mathf.Max(0,dt);bool previous=aiming;aiming=aim;focused=inspecting=false;if(previous!=aiming&&aimSound&&gearAudio)gearAudio.PlayOneShot(aimSound,.45f);RenderPose(dt,movement);}
 public void RenderPose(float dt,float movement){ads=Mathf.MoveTowards(ads,aiming?1:0,dt*6);recoilAngle*=Mathf.Exp(-dt*8);eye.transform.localRotation*=Quaternion.Euler(-recoilAngle.x,recoilAngle.y,-recoilAngle.y*.3f);recoil=Mathf.MoveTowards(recoil,0,dt*.28f);eye.fieldOfView=Mathf.Lerp(normalFieldOfView,focused?39:48,ads)-suppressionVisual*Mathf.Lerp(7,3,ads);
