 if(adsRifle)adsRifle.localPosition=new Vector3(-.02f*.85f,-.398f*.85f,.42f-recoil);if(focusRifle)focusRifle.localPosition=new Vector3(-.04f*.65f,-.39f*.65f,.48f-recoil);
 if(adsRifle)adsRifle.localRotation=adsRestRotation*Quaternion.Euler(-recoil*55,recoilAngle.y*.2f,0);if(focusRifle)focusRifle.localRotation=focusRestRotation*Quaternion.Euler(-recoil*40,recoilAngle.y*.12f,0);
 watch.gameObject.SetActive(inspecting);
 AlignMuzzle();if(muzzleFlash)muzzleFlash.enabled=t<flashUntil;if(muzzle)muzzle.gameObject.SetActive(t<flashUntil);
 }
