 public bool TryServiceRelay(){if(cinematicLocked||(fieldKit&&fieldKit.Busy)||(equipment&&equipment.HandsBusy)||(anatomy&&anatomy.Incapacitated)||(visorEffects&&visorEffects.Busy)||IsReloading||serviced||!nodeRepair||Vector3.Distance(transform.position,sensor.position)>=3)return false;aiming=false;focused=false;inspecting=false;pack.gameObject.SetActive(false);RenderPose(0,0);return nodeRepair.Begin();}
