 public void Preview(float time){if(body==null){body=GetComponent<CharacterController>();gunRest=rifle.localPosition;gunRot=rifle.localRotation;}t=time;inspecting=time>=8;aiming=time>=3&&time<8;focused=time>=6&&time<8;pitch=0;headYaw=time<3?Mathf.Sin(time*2)*22:0;eye.transform.localRotation=Quaternion.Euler(0,headYaw,0);if((time>=4&&time<4.06f)||(time>=5&&time<5.06f)){recoil=.035f;flashUntil=time+.04f;}RenderPose(1f/24,0);}
 void ResolveShot(){float spread=anatomy?anatomy.AimInstability:0;Vector3 direction=Quaternion.Euler(Random.Range(-spread,spread),Random.Range(-spread,spread),0)*eye.transform.forward;var hits=Physics.RaycastAll(eye.transform.position,direction,160,~0,QueryTriggerInteraction.Collide);System.Array.Sort(hits,(a,b)=>a.distance.CompareTo(b.distance));foreach(var hit in hits){if(hit.collider.transform.IsChildOf(transform))continue;var monster=hit.collider.GetComponentInParent<MedicalThornbackCrawl>();if(monster){monster.ReceiveHit(hit.point,direction);break;}var zone=hit.collider.GetComponent<WoodlandHitZone>();if(zone){zone.Receive(32,hit.point,direction);break;}if(!hit.collider.isTrigger)break;}}
 void OnGUI(){if(WoodlandDemoControls.Paused||cinematicLocked||(fieldKit&&fieldKit.Busy))return;string text=equipment&&equipment.ActionBusy?equipment.ActionLabel:IsReloading?"Reloading…":"";if(Time.unscaledTime<torchNoticeUntil)text=torchNotice;else if(battery<=0)text="Torch battery empty · "+(WoodlandDemoControls.UsingController?"Y":"F")+" replace cell";string prompt=string.IsNullOrEmpty(objectiveMessage)?message:objectiveMessage;if(prompt.StartsWith("E "))text=(WoodlandDemoControls.UsingController?"A ":"E ")+prompt.Substring(1).Trim();if(anatomy&&anatomy.Bleeding>0)text+="  •  Bleeding";if(anatomy&&anatomy.Incapacitated)text=WoodlandDemoControls.UsingController?"A  Return to checkpoint":"Enter  Return to checkpoint";if(text.Length==0)return;GUI.color=new Color(.85f,.9f,.8f,.9f);var style=new GUIStyle(GUI.skin.label){fontSize=15,alignment=TextAnchor.LowerCenter};GUI.Label(new Rect(0,Screen.height-45,Screen.width,30),text,style);}
